// Throwaway UI prototype: three structural layouts, selected with ?variant=A|B|C.
// All entities and actions are simulated, kept in memory, and never call TAPD/Git/Claude.
import '@phosphor-icons/web/regular';
import './style.css';

const $ = (s, root=document) => root.querySelector(s);
const icon = (name, cls='') => `<i class="ph ph-${name} ${cls}" aria-hidden="true"></i>`;
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn = (action, content, cls='', title='') => `<button data-action="${action}" class="${cls}" ${title?`title="${title}" aria-label="${title}"`:''}>${content}</button>`;
const pill = (text, cls='') => `<span class="pill ${cls}">${text}</span>`;
const params = new URLSearchParams(location.search);
const state = {
  variant: ['A','B','C'].includes(params.get('variant')) ? params.get('variant') : 'A',
  page:'workspace', tab:'context', selected:'lock', sidebar:true, context:true, chat:true,
  collapsed:new Set(['lanma-bankend','claude-picker']), query:'', filter:'all', selectedSource:'1049553',
  draft:'', commit:'feat: 支持订单批量锁定与解锁', modal:null, setting:'tapd', model:'Claude Sonnet', mode:'默认权限',
  effort:'标准', fast:false, running:false, approved:false, patchApproved:false, staged:false, committed:false, written:false,
  auto:false, font:13, messages:[], showAll:false,
};
const stories = [
  {id:'1049553',title:'订单解码流程优化',project:'lm-global',repo:'lm-global-java',type:'需求',status:'待实现',priority:'高',iteration:'V1.0 · 11月迭代',desc:'统一订单解码入口，明确手动解码与自动触发的处理路径，并补充失败原因与重试信息。'},
  {id:'1050360',title:'方果物流信息异步同步',project:'lm-global',repo:'lm-global-java',type:'需求',status:'实现中',priority:'高',iteration:'V1.0 · 11月迭代',desc:'将物流同步从主请求链路拆出，保留失败记录与重试入口，确保订单状态可追踪。'},
  {id:'1046781',title:'订单列表筛选与统计',project:'lm-global',repo:'lm-global-java',type:'需求',status:'待实现',priority:'中',iteration:'V1.0 · 11月迭代',desc:'补充订单列表条件筛选与头部统计，保证筛选与统计口径一致。'},
  {id:'1043436',title:'【线上问题】订单诊断信息缺失',project:'蓝马',repo:'lanma-bankend',type:'缺陷',status:'处理中',priority:'紧急',iteration:'V4.4 · 问题修复',desc:'部分订单没有显示诊断结果，需要定位异常并补充可供核查的错误信息。'},
];
const tasks = [
  {id:'lock',title:'订单批量锁定与解锁',source:'1049126',repo:'lm-global-java',status:'待回答',progress:3,total:5,branch:'v1.0/zengchangliang_orderLockUnlock',time:'8 分钟前',desc:'实现批量锁定、解锁与方果状态同步，确保并发操作的一致性。'},
  {id:'express',title:'方果物流信息异步同步',source:'1050360',repo:'lm-global-java',status:'执行中',progress:2,total:5,branch:'v1.0/zengchangliang_1050360_fangguoExpress',time:'3 分钟前',desc:'拆分同步链路，完善失败记录与重试逻辑。'},
  {id:'review',title:'订单列表筛选与统计',source:'1046781',repo:'lm-global-java',status:'待审阅',progress:4,total:5,branch:'v1.0/zengchangliang_1046781_orderList',time:'12 分钟前',desc:'筛选条件与统计口径已调整，请检查变更并确认交付。'},
  {id:'decode',title:'订单解码异常定位',source:'1043436',repo:'lanma-bankend',status:'排队中',progress:0,total:5,branch:'v4.4/zengchangliang_1043436_orderDiagnosis',time:'20 分钟前',desc:'定位解码异常并记录复现条件。'},
];
const task = () => tasks.find(t=>t.id===state.selected) || tasks[0];
const businessStatus = t => stories.find(s=>s.id===t.source)?.status || '实现中';
const statusClass = s => ({'执行中':'blue','待回答':'orange','待审阅':'purple','已完成':'green','排队中':'neutral'}[s]||'neutral');
function status(s){return pill(`<span class="dot ${s==='执行中'?'pulse':''}"></span>${s}`,statusClass(s))}
function count(s){return tasks.filter(t=>t.status===s).length}
function notify(text){$('#toast').innerHTML=icon('check-circle')+esc(text);$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}

function header(){return `<header class="titlebar"><div class="window-controls"><span></span><span></span><span></span></div>${btn('sidebar',icon('sidebar-simple'),'icon-button','切换项目侧栏')}<div class="project-picker">${btn('project-menu',`${icon('folder-simple')}<b>${esc(task().repo)}</b>${icon('caret-down')}`)}</div><span class="bar-separator"></span><div class="branch-name">${icon('git-branch')}<span>${esc(task().branch)}</span></div><nav class="topnav" aria-label="工作台导航">${[['workspace','chats-circle','工作空间'],['tapd','tray','TAPD 待办'],['tasks','squares-four','任务'],['git','git-diff','变更']].map(([id,i,n])=>btn(`page:${id}`,`${icon(i)}${n}${id==='tasks'?`<span class="nav-count">${tasks.filter(t=>t.status!=='已完成').length}</span>`:''}`,state.page===id?'active':'')).join('')}</nav><div class="title-end"><span class="prototype-label">交互原型 · 演示数据</span>${btn('settings',icon('gear-six'),'icon-button','设置')}</div></header>`}
function sidebar(){return `<aside class="sidebar ${state.sidebar?'':'collapsed'}"><div class="side-heading"><span class="brand-mark">${icon('asterisk')}</span><strong>Claude Picker</strong>${btn('search',icon('magnifying-glass'),'icon-button','全局搜索')}</div><div class="sidebar-links">${btn('page:tapd',`${icon('tray')}<span>我的待办</span><small>${stories.length}</small>`,state.page==='tapd'?'selected':'')}${btn('page:tasks',`${icon('squares-four')}<span>Work 中心</span><span class="notification-count">${count('待回答')+count('待审阅')}</span>`,state.page==='tasks'?'selected':'')}</div><div class="section-label">项目与会话 ${btn('new-session',icon('plus'),'icon-button','新建会话')}</div><div class="project-tree">${['lm-global-java','lanma-bankend','claude-picker'].map(repo=>`<div class="tree-project">${btn(`collapse:${repo}`,`${icon(state.collapsed.has(repo)?'caret-right':'caret-down')}${icon('folder-simple')}<span>${repo}</span><small>${tasks.filter(t=>t.repo===repo).length||2}</small>`,'project-row')} ${!state.collapsed.has(repo)?`<div class="sessions">${tasks.filter(t=>t.repo===repo).map(t=>btn(`task:${t.id}`,`<span class="session-indicator ${statusClass(t.status)}"></span><span>${esc(t.title)}</span>${t.status==='待回答'?icon('chat-circle-dots'):''}`,`session ${state.selected===t.id?'selected':''}`)).join('')}${repo==='lm-global-java'?btn('history',`${icon('clock-counter-clockwise')}<span>展开其余 3 条会话</span>`,'history'):''}${repo==='claude-picker'?btn('new-session','图形聊天与 TAPD 融合设计','session'):''}</div>`:''}</div>`).join('')}</div><div class="sidebar-bottom"><div class="agent-capacity"><div>${icon('cpu')}<span>执行队列</span><b>${count('执行中')} / 2</b></div><div class="capacity-track"><span style="width:${count('执行中')/2*100}%"></span></div><small>${count('排队中')} 个任务等待执行</small></div>${btn('settings:tapd',`${icon('plugs-connected')}<span>TAPD 已连接</span><span class="small-dot green"></span>`,'connection')}${btn('settings',`<span class="avatar">曾</span><span>曾长亮<small>本地工作空间</small></span>${icon('gear-six')}`,'profile')}</div></aside>`}
function workspace(){return `<section class="workspace ${!state.chat?'chat-hidden':''} ${state.variant==='C'?'focus-layout':''}">${state.chat?`<div class="chat-panel">${chat()}</div>`:""}${state.context?`<div class="resizer" role="separator" aria-label="调整详情栏宽度"></div><aside class="context-panel">${context()}</aside>`:''}</section>${!state.chat?floatingComposer():''}`}
function chat(){let t=task();if(t.workId)return workChat(t);return `<div class="chat-heading"><div><div class="eyebrow">${icon('chat-circle-text')} 图形会话 <span class="slash">/</span> <span>${t.workId?t.workId+' · 企业微信':t.source?'TAPD #'+t.source:'本地会话'}</span></div><h1>${esc(t.title)}</h1></div><div class="heading-actions">${btn('collapse-chat',icon('minus-square'),'icon-button','收起对话')}${btn('context',icon('sidebar'),'icon-button','切换任务详情')}</div></div><div class="conversation" id="conversation"><div class="date-divider"><span>今天，14:32</span></div><div class="user-message"><div class="user-avatar">曾</div><div><div class="message-meta">你 <span>14:32</span></div><p>${esc(t.desc)}</p>${t.workId?`<button class="source-chip work-chip" data-action="work-source">${icon('chats-circle')}${esc(t.workId)}<span>企业微信 · WorkBuddy</span>${icon('arrow-up-right')}</button>`:t.source?`<button class="source-chip" data-action="source-detail">${icon('link')}TAPD #${t.source}<span>需求上下文已关联</span>${icon('arrow-up-right')}</button>`:''}</div></div><div class="assistant-message"><div class="assistant-avatar">${icon('asterisk')}</div><div class="message-body"><div class="message-meta">Claude <span>${state.model.replace('Claude ','')} · 当前工作树</span></div><p>我会先核对需求与现有实现，再分步骤完成修改。涉及业务口径的地方，会先与你确认。</p><div class="work-plan"><div class="plan-title">${icon('list-checks')}执行计划 <small>${t.progress} / ${t.total}</small></div>${['读取需求与关联上下文','定位实现与影响范围','修改代码并补充验证','审阅变更与验证结果',t.workId?'向 WorkBuddy 汇报结果':'生成 TAPD 回填草稿'].map((x,i)=>`<div class="plan-step ${i<t.progress?'done':''}">${icon(i<t.progress?'check-circle':i===t.progress?'circle-dashed':'circle')}<span>${x}</span>${i===t.progress?`<small>${t.status==='待回答'?'等待确认':t.status==='排队中'?'等待执行':'当前步骤'}</small>`:''}</div>`).join('')}</div><button class="tool-row" data-action="tool-detail"><span class="tool-icon">${icon('file-text')}</span><b>Read</b><code>OrderLockService.java</code><span>已读取</span>${icon('caret-right')}</button><button class="tool-row" data-action="page:git"><span class="tool-icon">${icon('git-diff')}</span><b>Edit</b><code>OrderLockService.java</code><em>+42 −8</em>${icon('caret-right')}</button><p>已整理批量处理路径，并将同一订单的并发操作放到共享锁内。还有一个业务行为需要确定：</p>${t.status==='待回答'?questionCard():t.status==='待审阅'?reviewCard():t.status==='已完成'?`<div class="success-note">${icon('check-circle')}已确认交付，可查看 TAPD 回填记录。</div>`:`<div class="running-note">${icon('circle-notch','spin')} ${t.status==='排队中'?'等待可用执行位置':'正在检查修改与验证结果…'}</div>`}</div></div>${state.messages.filter(m=>m.task===t.id).map(m=>`<div class="user-message appended"><div class="user-avatar">曾</div><div><div class="message-meta">你 <span>刚刚</span></div><p>${esc(m.text)}</p></div></div><div class="assistant-message appended"><div class="assistant-avatar">${icon('asterisk')}</div><div class="message-body"><p>已记录这条补充要求，会结合当前任务上下文继续处理。</p><small class="muted">演示回复</small></div></div>`).join('')}</div>${composer()}`}
function questionCard(){return `<section class="question-card"><div class="question-head">${icon('chat-circle-dots')}<strong>需要你确认</strong>${pill('业务口径','orange')}</div><h3>方果同步失败时，如何处理本地锁定状态？</h3><p>这会影响本地与外部系统的一致性。请选择处理方式，任务将依据你的选择继续。</p><label class="choice"><input type="radio" name="sync-choice" value="rollback" checked><span><b>回滚本地操作</b><small>外部同步失败时，恢复本地锁定状态</small></span></label><label class="choice"><input type="radio" name="sync-choice" value="retry"><span><b>保留本地结果，记录失败并重试</b><small>本地操作优先，外部状态允许延后同步</small></span></label><div class="card-actions"><span>任务已暂停，等待回答</span>${btn('answer',`确认并继续 ${icon('arrow-right')}`,'primary')}</div></section>`}
function reviewCard(){return `<section class="review-card"><div>${icon('check-circle')}<strong>修改已准备好，等待你审阅</strong></div><p>3 个文件发生变更。验证结果与交付摘要已整理。</p><div class="card-actions"><span class="green-text">${icon('check')} 聚焦检查通过 · 演示</span>${btn('page:git',`审阅变更 ${icon('arrow-right')}`,'primary')}</div></section>`}
function composer(floating=false){return `<div class="composer-wrap ${floating?'floating-composer':''}">${floating?`<div class="floating-handle">${icon('dots-six')}<span>继续对话</span>${btn('restore-chat',icon('arrows-out-simple'),'icon-button','恢复对话')}</div>`:''}<form id="message-form" class="composer"><textarea id="message" aria-label="发送给 Claude 的消息" placeholder="继续描述需求，或 @ 引用文件…" rows="2">${esc(state.draft)}</textarea><div class="composer-tools"><div>${btn('attach',icon('plus'),'icon-button','添加上下文')}${btn('mode',esc(state.mode),'text-button')}${btn('model',esc(state.model),'text-button')}${btn('effort',esc(state.effort),'text-button')}${btn('fast',icon('lightning'),`icon-button ${state.fast?'orange-text':''}`,'快速模式')}</div><div><span class="context-ring" title="演示上下文：32k / 200k">16%</span>${state.running?btn('stop',icon('stop'),'send stop','停止生成'):`<button type="submit" class="send" aria-label="发送消息">${icon('arrow-up')}</button>`}</div></div></form><div class="composer-foot"><span>${icon('git-branch')} 独立工作树</span><span>⌘ Enter 发送 · 所有操作为演示</span></div></div>`}
function floatingComposer(){return composer(true)}
function context(){let t=task();return `<div class="panel-tabs">${[['context','任务详情'],['files','变更文件'],['activity','活动']].map(([v,n])=>btn(`context-tab:${v}`,n,state.tab===v?'active':'')).join('')}${btn('context',icon('x'),'icon-button','关闭详情')}</div><div class="context-content">${state.tab==='context'&&t.workId?workContext(t):state.tab==='files'?filePanel():state.tab==='activity'?activity():`<div class="context-section"><div class="section-title">${icon('clipboard-text')}关联需求${btn('source-detail',icon('arrow-up-right'),'icon-button','查看关联需求')}</div><button class="source-box" data-action="source-detail"><div><span class="tapd-logo">T</span><span>TAPD</span><code>#${t.source}</code></div><strong>${esc(t.title)}</strong><small>${t.repo==='lanma-bankend'?'蓝马 · V4.4':'lm-global · V1.0'} 11月迭代</small></button><dl class="metadata"><div><dt>业务状态</dt><dd>${pill(businessStatus(t),'blue')}</dd></div><div><dt>AI 执行状态</dt><dd>${status(t.status)}</dd></div><div><dt>负责人</dt><dd><span class="mini-avatar">曾</span>曾长亮</dd></div><div><dt>排期</dt><dd class="muted">待 TAPD 排期</dd></div></dl></div><div class="context-section"><div class="section-title">${icon('git-branch')}开发环境</div><div class="environment-row"><span>项目</span><b>${t.repo}</b></div><div class="code-box">${icon('git-branch')}<code>${esc(t.branch)}</code></div><div class="environment-row"><span>隔离方式</span><b>独立 Git worktree</b></div><div class="environment-row"><span>执行器</span><b>Claude Code</b></div></div><div class="context-section"><div class="section-title">${icon('files')}本次变更<span class="tiny-count">3</span>${btn('page:git',icon('arrow-right'),'icon-button','查看全部变更')}</div>${fileList()}</div><div class="context-section"><div class="section-title">${icon('check-square')}交付检查</div><div class="checkline">${icon('check-circle','green-text')}需求上下文已关联</div><div class="checkline">${icon('check-circle','green-text')}开发工作树已隔离</div><div class="checkline">${icon(t.status==='待审阅'?'check-circle':'circle',t.status==='待审阅'?'green-text':'')}代码验证与审阅</div><div class="checkline">${icon(state.written?'check-circle':'circle',state.written?'green-text':'')}TAPD 回填${state.written?'已完成':'待确认'}</div></div><div class="context-tip">${icon('info')}代码提交与 TAPD 业务状态分别管理，回填前可预览。</div>`}</div>`}
const files = [{name:'OrderLockService.java',path:'service/impl',add:42,del:8},{name:'BatchLockRequest.java',path:'controller/vo',add:18,del:0},{name:'OrderLockServiceTest.java',path:'src/test/java',add:64,del:2}];
function fileList(){return files.map((f,i)=>`<button class="file-row" data-action="file:${i}">${icon('file-code')}<span>${f.name}<small>${f.path}</small></span><em>+${f.add}</em></button>`).join('')}
function filePanel(){if(task().workId)return `<div class="context-section"><div class="section-title">${icon('files')}Work 变更</div><p class="setting-hint">执行后，文件变更与验证结果将关联到 ${esc(task().workId)}。当前展示流程设计，未读取项目文件。</p>${btn('page:git','打开审阅与 Work 汇报','secondary full')}</div>`;return `<div class="context-section"><div class="section-title">变更文件 <span class="tiny-count">3</span></div>${fileList()}<div class="change-summary"><span>+124</span><b>−10</b></div>${btn('page:git','打开变更审阅','primary full')}</div>`}
function activity(){if(task().workId)return `<div class="activity-list">${[['chats-circle','收到企业微信消息',task().chat],['robot','WorkBuddy 整理并确认需求',task().workId],['folder-simple','关联项目',task().repo],['cpu','Work 当前状态',task().status]].map(([i,title,sub])=>`<div class="activity-item"><span>${icon(i)}</span><div><strong>${title}</strong><p>${esc(sub)}</p><small>演示事件</small></div></div>`).join('')}</div>`;return `<div class="activity-list">${[['14:40','chat-circle-dots','等待业务口径确认','方果同步失败的处理策略'],['14:38','git-diff','完成代码修改','3 个文件 · +124 −10'],['14:35','magnifying-glass','定位业务实现','OrderLockService.java'],['14:32','git-branch','创建独立工作树','从仓库基线创建'],['14:32','link','关联 TAPD 需求','#'+task().source]].map(([time,i,title,sub])=>`<div class="activity-item"><span>${icon(i)}</span><div><strong>${title}</strong><p>${esc(sub)}</p><small>${time}</small></div></div>`).join('')}</div>`}

function taskCard(t){return `<button data-action="task:${t.id}" class="task-card"><div class="task-card-top"><span class="source-id">${icon(t.workId?'chats-circle':'link')} ${t.workId?esc(t.workId):t.source?'#'+t.source:'本地'}</span>${icon('dots-three')}</div><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p><div class="task-card-env">${icon('folder-simple')} ${t.repo}</div><div class="task-progress"><span style="width:${t.progress/t.total*100}%"></span></div><div class="task-card-bottom"><span class="mini-avatar">曾</span><span>${t.progress}/${t.total} 步</span><small>${t.time}</small></div></button>`}
function board(){return `<section class="page board-page"><div class="page-heading"><div><div class="eyebrow">AGENT WORKSPACE</div><h1>让任务持续向前。</h1><p>从需求到交付，在需要你时找到你。</p></div><div>${btn('page:tapd',`${icon('tray')} 从 TAPD 导入`,'secondary')}${btn('new-task',`${icon('plus')}新建 Work`,'primary')}</div></div><div class="overview-strip"><div><span>进行中的任务</span><strong>${tasks.filter(t=>t.status!=='已完成').length}<small>个</small></strong></div><div><span>需要你的关注</span><strong class="orange-text">${count('待回答')+count('待审阅')}<small>个</small></strong></div><div><span>执行位置</span><strong>${count('执行中')}<small>/ 2</small></strong></div><div class="strip-note">${icon('shield-check')}<span>每个任务独立工作树<br><small>任务准备好后，由你审阅交付</small></span></div></div><div class="board-toolbar"><div class="segmented">${btn('board-view','看板','active')}${btn('task-list','列表')}</div><span>${icon('folder-simple')}所有项目</span><div class="board-legend"><span class="small-dot blue"></span>正在同步任务状态</div></div><div class="kanban">${[['排队中','circle-dashed'],['执行中','circle-notch'],['待回答','chat-circle-dots'],['待审阅','git-pull-request']].map(([s,i])=>`<section class="kanban-column"><div class="column-title"><span class="${statusClass(s)}-text">${icon(i)}</span><h2>${s}</h2><span>${count(s)}</span>${btn('new-task',icon('plus'),'icon-button',`新建${s}任务`)}</div>${tasks.filter(t=>t.status===s).map(taskCard).join('')}${!count(s)?`<div class="empty-column">暂无${s}任务</div>`:''}</section>`).join('')}</div><div class="board-footer">${icon('info')}演示任务，不代表实际 TAPD 状态或代码交付结果。</div></section>`}
function tapd(){const list=stories.filter(s=>(state.filter==='all'||state.filter===s.project)&&(s.title+s.id).includes(state.query));let s=stories.find(s=>s.id===state.selectedSource)||stories[0];return `<section class="page tapd-page"><div class="page-heading"><div><div class="eyebrow">CONNECTED WORKSPACE</div><h1>TAPD 待办</h1><p>把需求带入工作空间，让上下文与任务同行。</p></div><div><span class="sync-label">${icon('check-circle')} 演示连接</span>${btn('refresh',icon('arrows-clockwise')+' 刷新','secondary')}${btn('settings:tapd',icon('gear-six'),'icon-button','TAPD 连接设置')}</div></div><div class="tapd-toolbar"><div class="project-filters">${[['all','全部项目'],['lm-global','lm-global'],['蓝马','蓝马']].map(([f,l])=>btn(`filter:${f}`,`${l}${f==='all'?`<span>${stories.length}</span>`:''}`,state.filter===f?'active':'')).join('')}</div><label class="search-box">${icon('magnifying-glass')}<input id="tapd-search" aria-label="搜索 TAPD 待办" placeholder="搜索标题或编号" value="${esc(state.query)}"><kbd>⌘ K</kbd></label></div><div class="tapd-columns"><div class="story-list"><div class="list-label"><span>分配给我的待办</span><span>${list.length} 项</span></div>${list.length?list.map(s=>`<button data-action="source:${s.id}" class="story-row ${s.id===state.selectedSource?'selected':''}"><span class="entity-icon ${s.type==='缺陷'?'red':''}">${icon(s.type==='缺陷'?'bug':'book-open')}</span><div><div class="story-id">${s.project} <span>/</span> #${s.id}</div><h3>${s.title}</h3><div class="story-meta">${pill(s.priority,s.priority==='紧急'?'red':s.priority==='高'?'orange':'neutral')}<span>${s.iteration}</span></div></div>${pill(s.status,'neutral')}</button>`).join(''):`<div class="empty-state">${icon('magnifying-glass')}没有找到匹配的待办</div>`}</div><aside class="story-detail"><div class="detail-type"><span class="tapd-logo">T</span>TAPD ${s.type}<code>#${s.id}</code></div><h2>${s.title}</h2><dl class="metadata"><div><dt>业务状态</dt><dd>${pill(s.status,'blue')}</dd></div><div><dt>负责人</dt><dd><span class="mini-avatar">曾</span>曾长亮</dd></div><div><dt>所属迭代</dt><dd>${s.iteration}</dd></div><div><dt>关联仓库</dt><dd>${icon('folder-simple')}${s.repo}</dd></div><div><dt>计划时间</dt><dd class="muted">待 TAPD 排期</dd></div></dl><div class="detail-section"><h3>需求描述</h3><p>${s.desc}</p><h3>验收要点</h3><ul><li>覆盖正常与异常处理路径</li><li>操作结果及失败原因可追踪</li><li>不影响现有订单处理流程</li></ul></div><div class="attachment">${icon('paperclip')}需求说明与原型附件 <small>演示内容</small></div><div class="source-note">${icon('info')}导入会创建本地 AI 任务，TAPD 状态保持独立。</div>${btn(`import:${s.id}`,`${icon('plus-circle')} 创建开发任务`,'primary full')}</aside></div></section>`}
function diff(){return `<div class="diff-toolbar"><div>${icon('file-code')}<strong>${files[state.file||0].name}</strong><span>工作树变更</span></div><div class="diff-stats"><span>+${files[state.file||0].add}</span><b>−${files[state.file||0].del}</b></div></div><div class="diff-hunk">@@ −128,12 +128,20 @@ public void batchLock(...)</div><div class="code-diff">${[
['context','128','128','public void batchLock(BatchLockRequest request) {'],['context','129','129','    List<Long> orderIds = request.getOrderIds();'],['remove','130','','    orderMapper.updateLockStatus(orderIds, true);'],['add','','130','    for (Long orderId : orderIds) {'],['add','','131','        orderLock.execute(orderId, () -> {'],['add','','132','            Order order = requireOrder(orderId);'],['add','','133','            validateLockStatus(order);'],['add','','134','            orderMapper.updateLockStatus(orderId, true);'],['add','','135','            syncLockStatus(orderId, true);'],['add','','136','        });'],['add','','137','    }'],['context','131','138','}'],['context','','',''],['context','133','140','private void syncLockStatus(Long orderId, boolean locked) {'],['remove','134','','    fangguoClient.sync(orderId, locked);'],['add','','141','    SyncResult result = fangguoClient.sync(orderId, locked);'],['add','','142','    if (!result.isSuccess()) {'],['add','','143','        handleSyncFailure(orderId, result);'],['add','','144','    }'],['context','135','145','}']].map(([cls,old,num,line])=>`<div class="code-line ${cls}"><span>${old}</span><span>${num}</span><b>${cls==='add'?'+':cls==='remove'?'−':''}</b><code>${esc(line)}</code></div>`).join('')}</div>`}
function git(){return `<section class="git-page"><div class="git-heading"><div><div class="eyebrow">REVIEW & DELIVERY</div><h1>变更审阅</h1></div><div>${pill('独立工作树','neutral')}${btn('workspace-return',`${icon('chat-circle')}返回对话`,'secondary')}</div></div><div class="git-layout"><aside class="git-files"><div class="section-title">${icon('git-diff')}变更文件<span class="tiny-count">3</span></div>${fileList()}<div class="git-divider"></div><div class="section-title">${icon('check-circle','green-text')}验证结果</div><div class="validation"><div>${icon('check','green-text')}聚焦测试 <small>通过</small></div><div>${icon('check','green-text')}编译检查 <small>通过</small></div><div>${icon('check','green-text')}差异检查 <small>通过</small></div><p>以上均为原型演示结果。</p></div><div class="commit-box"><label for="commit-msg">提交信息</label><textarea id="commit-msg" rows="3">${esc(state.commit)}</textarea>${btn('stage',`${icon(state.staged?'check':'plus')} ${state.staged?'已暂存 3 个文件':'暂存全部变更'}`,'secondary full')}${btn('commit',`${icon('git-commit')} ${state.committed?'已创建演示提交':'创建提交'}`,'primary full')}</div></aside><div class="diff-panel">${diff()}</div></div><footer class="review-footer"><div>${icon(state.patchApproved?'check-circle':'git-pull-request',state.patchApproved?'green-text':'')}<span>${state.patchApproved?'变更已确认，可预览交付回填':'审阅完成后，再确认交付结果'}</span></div><div>${btn('approve-review',`${icon('check')} ${state.patchApproved?'已确认变更':'确认变更'}`,'secondary')}${btn('writeback',`${icon('arrow-square-out')}${task().workId?'预览 Work 汇报':'预览 TAPD 回填'}`,'primary')}</div></footer></section>`}
function render(){document.documentElement.style.setProperty('--ui-font',state.font+'px');$('#app').innerHTML=`<div class="app-shell variant-${state.variant}">${header()}<div class="app-body">${sidebar()}<main class="main-content">${state.page==='tapd'?tapd():state.page==='tasks'||(state.variant==='B'&&state.page==='workspace')?board():state.page==='git'?git():workspace()}</main></div></div>${switcher()}`;bindDrag();console.info('[prototype state]',{variant:state.variant,page:state.page,task:state.selected,status:task().status});}
function switcher(){return `<div class="prototype-switcher"><span class="switcher-tag">布局探索</span>${btn('variant-prev',icon('caret-left'),'icon-button','上一种布局')}<div class="variant-options">${[['A','工作空间'],['B','任务看板'],['C','专注对话']].map(([v,n])=>btn(`variant:${v}`,`<b>${v}</b>${n}`,state.variant===v?'active':'')).join('')}</div>${btn('variant-next',icon('caret-right'),'icon-button','下一种布局')}<span class="switcher-state">${state.page==='workspace'?'会话':{tasks:'任务',tapd:'TAPD',git:'审阅'}[state.page]} · ${task().status}</span></div>`}
function setVariant(v){state.variant=v;state.page='workspace';state.context=v!=='C';state.chat=true;const url=new URL(location);url.searchParams.set('variant',v);history.replaceState({},'',url);console.info('[prototype state]',{variant:v,page:state.page,task:state.selected,status:task().status});render()}
const sessionState = new Map();
const localKeys=['draft','commit','running','approved','patchApproved','staged','committed','written'];
function rememberTask(){sessionState.set(state.selected,Object.fromEntries(localKeys.map(k=>[k,state[k]])))}
function openTask(id){rememberTask();Object.assign(state,{draft:'',commit:'feat: '+(tasks.find(t=>t.id===id)?.title||'开发任务'),running:false,approved:false,patchApproved:false,staged:false,committed:false,written:false},sessionState.get(id)||{});state.selected=id;state.page='workspace';state.chat=true;if(state.variant==='B'){state.variant='A';const url=new URL(location);url.searchParams.set('variant','A');history.replaceState({},'',url)}render()}

function modal(title, body, footer='', wide=false){state.modal=title;$('#layer').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><div class="eyebrow">CLAUDE PICKER</div><h2>${title}</h2></div>${btn('close-modal',icon('x'),'icon-button','关闭弹窗')}</header><div class="modal-body">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;setTimeout(()=>$('#layer input:not([type=checkbox]), #layer textarea')?.focus(),0)}
function closeModal(){state.modal=null;$('#layer').innerHTML=''}
function importModal(id){let s=stories.find(x=>x.id===id);state.importId=id;modal('创建开发任务',`<div class="import-source"><span class="tapd-logo">T</span><div><small>TAPD ${s.project} · #${s.id}</small><h3>${s.title}</h3></div></div><label class="field">任务名称<input id="task-name" value="${s.title}"></label><div class="form-grid"><label class="field">本地仓库<select id="task-repo"><option>${s.repo}</option><option>claude-picker</option><option>lanma-bankend</option></select></label><label class="field">执行器<select><option>Claude Code</option></select></label></div><label class="field">工作目录策略<select><option>创建独立 Git worktree</option></select><small>根据所选仓库规范创建分支，任务之间互不覆盖。</small></label><label class="check-option"><input id="start-immediately" type="checkbox" checked>创建后启动任务</label><div class="source-note">${icon('info')}只创建本地演示任务，不修改 TAPD 需求状态。</div>`,btn('close-modal','取消','secondary')+btn('create-import',icon('plus')+'创建任务','primary'))}
function settings(){const body=`<div class="settings-layout"><nav>${[['appearance','sliders-horizontal','界面与会话'],['tapd','plugs-connected','TAPD 连接'],['wecom','chat-circle-dots','企业微信机器人'],['mcp','puzzle-piece','MCP 服务']].map(([k,i,n])=>btn(`setting:${k}`,icon(i)+n,state.setting===k?'active':'')).join('')}</nav><div class="settings-detail">${state.setting==='wecom'?robotSettings():state.setting==='tapd'?`<h3>TAPD 连接</h3><p>将需求与本地项目关联，在一个工作空间中推进。</p><div class="connected-account">${icon('check-circle','green-text')}<div><b>曾长亮</b><small>演示连接 · 只读与受控回填</small></div>${pill('已连接','green')}</div><h4>项目与仓库映射</h4><div class="mapping-row"><span>lm-global</span>${icon('arrow-right')}<code>lm-global-java</code></div><div class="mapping-row"><span>蓝马</span>${icon('arrow-right')}<code>lanma-bankend</code></div>${btn('add-mapping',icon('plus')+'添加映射','secondary')}<h4>同步与回填</h4><label class="check-option"><input type="checkbox" checked>启动时同步我的待办</label><label class="check-option"><input type="checkbox" checked>回填前展示变更预览</label><label class="check-option"><input id="auto-task" type="checkbox" ${state.auto?'checked':''}>允许按规则自动创建任务</label><small class="muted">本原型不连接真实 TAPD，也不保存凭据。</small>`:state.setting==='mcp'?`<h3>MCP 服务</h3><p>为会话提供额外的工具和上下文。</p>${['TAPD','GitHub','Filesystem'].map(n=>`<div class="mcp-service"><span>${icon('puzzle-piece')}<b>${n}</b><small>${n==='TAPD'?'需求、任务与评论':'工具服务'}</small></span><label class="toggle-label"><input type="checkbox" checked aria-label="启用 ${n}"></label></div>`).join('')}${btn('mcp-tools','查看 TAPD 工具','secondary')}`:`<h3>界面与会话</h3><p>保留熟悉的桌面操作方式。</p><label class="field">界面字号<input id="font-slider" type="range" min="12" max="15" value="${state.font}"><small>${state.font} px</small></label><label class="field">交互模式<select><option>图形聊天（实验）</option><option>原生终端（回退入口）</option></select></label><label class="check-option"><input type="checkbox" checked>打开会话时，Git 工作台跟随会话分支</label><label class="field">主题<select><option>深色 · 暖橙</option></select></label><label class="field">终端字号（原生模式）<input type="range" min="11" max="20" value="13"></label>`}</div></div>`;modal('设置',body,btn('close-modal','完成','primary'),true)}
function writeback(){if(task().workId){workDelivery();return}modal('TAPD 回填预览',`<div class="write-target"><span class="tapd-logo">T</span><div><small>${task().repo} · #${task().source}</small><b>${task().title}</b></div>${pill('评论','neutral')}</div><label class="field">回填内容<textarea id="writeback-text" rows="8">实现摘要：已整理本次任务的代码修改。

变更范围：3 个文件，+124 / −10（演示）。
验证结果：聚焦测试、编译与差异检查通过（演示）。
交付证据：${state.committed?'已创建演示提交':'尚未创建提交，待补充真实链接'}。
待办事项：请确认业务验收与后续发布安排。</textarea></label><div class="writeback-status"><div>业务状态 ${pill('实现中','blue')} ${icon('arrow-right')} ${pill('保持不变','neutral')}</div><p>此处只演示添加评论，不据此标记完成、上线或填写工时。</p></div>${!state.patchApproved?`<div class="warning-note">${icon('warning-circle')}尚未确认变更，请先完成审阅。</div>`:''}`,btn('close-modal','返回','secondary')+btn('confirm-writeback','模拟确认回填','primary'))}


// WorkBuddy is an interaction channel here, not the code executor. No real API is called.
const robot={name:'开发协作助手',enabled:true,trigger:'mentioned',chat:'研发协作群',request:'@开发协作助手 帮我在 claude-picker 项目里优化会话搜索，支持按标题和项目过滤。',lastWork:null,serial:1001,saved:false,mappings:[{chat:'研发协作群',repo:'claude-picker'},{chat:'订单服务群',repo:'lm-global-java'}]};
function workChat(t){return `<div class="chat-heading"><div><div class="eyebrow">${icon('briefcase')}${esc(t.workId)}<span class="slash">/</span>企业微信发起</div><h1>${esc(t.title)}</h1></div><div class="heading-actions">${btn('collapse-chat',icon('minus-square'),'icon-button','收起对话')}${btn('context',icon('sidebar'),'icon-button','切换任务详情')}</div></div><div class="conversation" id="conversation"><div class="date-divider"><span>WorkBuddy 已转交需求</span></div><div class="user-message"><div class="user-avatar">曾</div><div><div class="message-meta">你<span>企业微信 · ${esc(t.chat)}</span></div><p>${esc(t.desc)}</p><button class="source-chip work-chip" data-action="work-source">${icon('chats-circle')}WorkBuddy 原始对话${icon('arrow-up-right')}</button></div></div><div class="assistant-message"><div class="assistant-avatar">${icon('asterisk')}</div><div class="message-body"><div class="message-meta">Claude Code<span>代码执行器 · ${esc(t.repo)}</span></div><p>已接收 WorkBuddy 整理的工作目标。这个 Work 独立归属于当前项目，后续问题与结果会关联到原企业微信会话。</p><div class="work-plan"><div class="plan-title">${icon('list-checks')}Work 执行计划<small>${t.progress} / 5</small></div>${['确认项目与工作目标','准备独立工作树','执行代码修改与验证','等待审阅交付','由 WorkBuddy 向原会话汇报'].map((x,i)=>`<div class="plan-step ${i<t.progress?'done':''}">${icon(i<t.progress?'check-circle':'circle')}<span>${x}</span></div>`).join('')}</div><div class="work-state-card">${status(t.status)}<p>${t.status==='排队中'?'工作目标已确认，可模拟启动执行。':t.status==='执行中'?'正在模拟项目执行，完成后交给你审阅。':t.status==='已完成'?'结果已交给 WorkBuddy，原会话可以查看汇报。':'执行结果已整理，请审阅变更后汇报。'}</p>${t.status==='排队中'?btn('work-start',icon('play')+'模拟启动 Work','primary'):t.status==='待审阅'?btn('page:git',icon('git-diff')+'审阅演示变更','primary'):t.status==='已完成'?btn('work-source','查看结果回复','secondary'):''}</div></div></div>${state.messages.filter(m=>m.task===t.id).map(m=>`<div class="user-message appended"><div class="user-avatar">曾</div><p>${esc(m.text)}</p></div>`).join('')}</div>${composer()}`}
function saveRobot(){if(!$('#robot-name'))return;robot.name=$('#robot-name').value.trim()||'开发协作助手';robot.enabled=$('#robot-enabled').checked;robot.trigger=$('#robot-trigger').value;robot.mappings.forEach((m,i)=>m.repo=$('#robot-repo-'+i).value);robot.saved=true}
function robotSettings(){return `<div class="robot-heading"><div class="robot-logo">${icon('chats-circle')}</div><div><h3>企业微信机器人</h3><p>由 WorkBuddy 与人交流，将需求交给项目中的 Work。</p></div></div><div class="robot-connection"><div>${icon('plugs-connected')}<b>WorkBuddy</b><small>对话接入与消息回复</small></div>${pill(robot.enabled?'演示已绑定':'已停用',robot.enabled?'green':'neutral')}</div><div class="robot-flow"><span>企业微信</span>${icon('arrow-right')}<span>WorkBuddy</span>${icon('arrow-right')}<b>项目 / Work</b></div><div class="form-grid"><label class="field">机器人名称<input id="robot-name" value="${esc(robot.name)}" autocomplete="off"></label><label class="field">接收方式<select id="robot-trigger"><option value="mentioned" ${robot.trigger==='mentioned'?'selected':''}>群内 @机器人 + 私聊</option><option value="direct" ${robot.trigger==='direct'?'selected':''}>仅私聊</option></select></label></div><label class="check-option"><input id="robot-enabled" type="checkbox" ${robot.enabled?'checked':''}>启用企业微信对话入口</label><h4>群聊与项目映射</h4><p class="setting-hint">未匹配项目时，先在对话中询问，再创建 Work。</p>${robot.mappings.map((m,i)=>`<div class="robot-mapping"><span>${icon('users-three')}${esc(m.chat)}</span>${icon('arrow-right')}<select id="robot-repo-${i}" aria-label="${esc(m.chat)}关联项目">${['claude-picker','lm-global-java','lanma-bankend'].map(r=>`<option ${r===m.repo?'selected':''}>${r}</option>`).join('')}</select></div>`).join('')}<h4>Work 创建与汇报</h4><div class="robot-rule">${icon('check-circle')}由 WorkBuddy 澄清需求并展示项目、目标与执行范围</div><div class="robot-rule">${icon('check-circle')}确认后在项目中创建独立 Work，关联会话与工作树</div><div class="robot-rule">${icon('check-circle')}问题与结果回到原企业微信会话，保留 Work 链接</div><div class="robot-setting-actions">${btn('robot-save',icon('floppy-disk')+'保存配置','secondary')}${btn('robot-demo',icon('chat-circle-text')+'体验对话 → Work','primary')}</div><div class="source-note">${icon('info')}演示配置。实际 WorkBuddy 接入、企业微信收发与认证方式待实现时核实。</div>`}
function robotDemo(work){if(!robot.enabled&&!work){notify('请先启用企业微信对话入口');return}if(work?.workId){modal('企业微信 · WorkBuddy 对话',`<div class="channel-heading">${icon('users-three')}<b>${esc(work.chat)}</b>${pill('演示会话','neutral')}</div><div class="robot-chat"><div class="human-bubble"><small>你</small><p>${esc(work.desc)}</p></div><div class="bot-bubble"><small>${esc(robot.name)} · WorkBuddy</small><p>已在 ${esc(work.repo)} 创建 ${esc(work.workId)}，会在这里同步需要你回答的问题和交付结果。</p><div class="work-link">${icon('briefcase')} ${esc(work.workId)} · ${esc(work.title)}</div></div>${work.delivery?`<div class="bot-bubble"><small>WorkBuddy · 结果汇报</small><p>${esc(work.delivery)}</p></div>`:''}</div><p class="setting-hint">这是原会话关联视图，不会发送真实消息。</p>`,btn('close-modal','关闭','secondary'));return}modal('企业微信 → 项目 Work',`<div class="channel-heading">${icon('chats-circle')}<b>${esc(robot.name)}</b>${pill('WorkBuddy 对话预览','green')}</div><label class="field">对话来源<select id="robot-chat">${robot.mappings.map(m=>`<option ${m.chat===robot.chat?'selected':''}>${esc(m.chat)}</option>`).join('')}</select></label><label class="field">用户消息<textarea id="robot-request" rows="3">${esc(robot.request)}</textarea></label><div class="bot-bubble"><small>WorkBuddy</small><p>我会识别你的需求与关联项目，整理目标后请你确认，再创建 Work。</p></div><div class="source-note">${icon('info')}Work 属于本应用项目。这个流程不会创建 TAPD 需求或任务。</div>`,btn('close-modal','取消','secondary')+btn('robot-preview',icon('arrow-right')+'整理为 Work','primary'))}
function previewRobotWork(){if(!robot.request){notify('请填写用户消息');return}let mapped=robot.mappings.find(m=>m.chat===robot.chat)?.repo;const explicit=['claude-picker','lm-global-java','lanma-bankend'].find(r=>robot.request.includes(r));robot.target=explicit||mapped||'';modal('确认创建 Work',`<div class="bot-bubble"><small>${esc(robot.name)} · WorkBuddy</small><p>我已把这条消息整理为项目工作。请确认项目和工作目标。</p></div><label class="field">Work 名称<input id="robot-work-title" value="${esc(robot.request.replace(/@\S+\s*/,''))}"></label><label class="field">关联项目<select id="robot-work-project"><option value="">请选择项目</option>${['claude-picker','lm-global-java','lanma-bankend'].map(r=>`<option ${r===robot.target?'selected':''}>${r}</option>`).join('')}</select></label><div class="work-origin"><span>${icon('chats-circle')}来源</span><b>企业微信 / ${esc(robot.chat)}</b></div><div class="work-origin"><span>${icon('robot')}对话服务</span><b>WorkBuddy</b></div><div class="work-origin"><span>${icon('cpu')}代码执行器</span><b>Claude Code</b></div><div class="work-origin"><span>${icon('git-branch')}执行环境</span><b>独立工作树 · 创建后排队</b></div><div class="source-note">${icon('info')}保留原消息与会话关联，后续追问和结果通过 WorkBuddy 回复。</div>`,btn('robot-return','返回修改','secondary')+btn('robot-create',icon('plus-circle')+'确认创建 Work','primary'))}
function createRobotWork(){let title=$('#robot-work-title').value.trim(),repo=$('#robot-work-project').value;if(!title||!repo){notify('请填写 Work 名称并选择项目');return}let workId='WORK-'+robot.serial++;let t={id:'work-'+Date.now(),workId,origin:'wecom',title,repo,source:null,status:'排队中',progress:0,total:5,branch:'codex/'+workId.toLowerCase(),time:'刚刚',desc:robot.request,chat:robot.chat};tasks.push(t);robot.lastWork=t.id;state.collapsed.delete(repo);modal('Work 已创建',`<div class="work-created">${icon('check-circle')}<h3>${workId}</h3><p>已关联到 ${esc(repo)}</p></div><div class="bot-bubble"><small>${esc(robot.name)} · WorkBuddy</small><p>已创建 ${workId}，进入项目执行队列。需要你回答问题或结果准备好时，我会在 ${esc(robot.chat)} 中回复。</p></div><div class="work-origin"><span>来源</span><b>企业微信 · 独立 Work</b></div>`,btn('robot-return','继续体验对话','secondary')+btn('robot-open',icon('arrow-right')+'打开项目 Work','primary'));render();notify('独立 Work 已创建 · 演示')}
function workContext(t){return `<div class="context-section"><div class="section-title">${icon('briefcase')}项目 Work ${pill('独立工作项','green')}</div><button class="source-box work-source" data-action="work-source"><div>${icon('chats-circle')}<span>企业微信 · WorkBuddy</span><code>${esc(t.workId)}</code></div><strong>${esc(t.title)}</strong><small>${esc(t.chat)}</small></button><dl class="metadata"><div><dt>项目</dt><dd>${esc(t.repo)}</dd></div><div><dt>Work 状态</dt><dd>${status(t.status)}</dd></div><div><dt>发起人</dt><dd><span class="mini-avatar">曾</span>曾长亮</dd></div><div><dt>对话服务</dt><dd>WorkBuddy</dd></div></dl></div><div class="context-section"><div class="section-title">${icon('git-branch')}执行环境</div><div class="code-box">${icon('git-branch')}<code>${esc(t.branch)}</code></div><div class="environment-row"><span>执行器</span><b>Claude Code</b></div><div class="environment-row"><span>工作目录</span><b>独立 Git worktree</b></div></div><div class="context-section"><div class="section-title">${icon('chats-circle')}对话与反馈</div><div class="robot-rule">${icon('check-circle')}原消息已保存并关联 Work</div><div class="robot-rule">${icon('circle')}业务疑问通过 WorkBuddy 询问</div><div class="robot-rule">${icon('circle')}审阅后汇报执行结果</div>${btn('work-source','查看企业微信对话','secondary full')}</div><div class="context-tip">${icon('info')}此 Work 由企业微信消息创建，归属于本地项目，不关联 TAPD 工作项。</div>`}
function workDelivery(){modal('Work 结果汇报',`<div class="write-target">${icon('briefcase')}<div><small>${esc(task().workId)} · ${esc(task().repo)}</small><b>${esc(task().title)}</b></div></div><label class="field">交给 WorkBuddy 的汇报<textarea id="work-delivery-text" rows="5">工作结果已整理，请在项目中审阅变更。确认后由 WorkBuddy 在原企业微信会话回复，附带 Work 编号与结果链接。（演示）</textarea></label><div class="work-origin"><span>回复位置</span><b>${esc(task().chat)} / WorkBuddy</b></div>${!state.patchApproved?'<p class="warning-note">请先确认变更，再完成汇报。</p>':''}`,btn('close-modal','返回','secondary')+btn('work-delivered','模拟交付并回复','primary'))}

document.addEventListener('click', e=>{let el=e.target.closest('[data-action]');if(!el){if(e.target.classList.contains('overlay'))closeModal();return}let [a,arg]=el.dataset.action.split(':');
  if(a==='work-start'){let w=task();w.status='执行中';w.progress=2;render();setTimeout(()=>{if(w.status==='执行中'){w.status='待审阅';w.progress=4;render();notify(w.workId+' 已准备好，等待审阅 · 演示')}},3500)}
  else if(a==='robot-save'){saveRobot();notify('机器人配置已保存 · 仅演示');settings()}
  else if(a==='robot-demo'){saveRobot();if(!robot.enabled){notify('请先启用机器人对话入口');return}robotDemo()}
  else if(a==='robot-preview'){robot.request=$('#robot-request').value.trim();robot.chat=$('#robot-chat').value;previewRobotWork()}
  else if(a==='robot-create'){createRobotWork()}
  else if(a==='robot-open'){closeModal();state.context=true;openTask(robot.lastWork);state.tab='context';render()}
  else if(a==='robot-return'){robotDemo()}
  else if(a==='work-source'){robotDemo(task())}
  else if(a==='work-delivered'){if(!state.patchApproved){notify('请先确认变更');return}let text=$('#work-delivery-text').value.trim();if(!text){notify('请填写汇报内容');return}task().status='已完成';task().progress=5;task().delivery=text;rememberTask();closeModal();render();notify('结果已回传至 WorkBuddy · 模拟，未发送企业微信消息')}
  else if(a==='page'){state.page=arg;render()}
  else if(a==='task')openTask(arg);
  else if(a==='variant')setVariant(arg);
  else if(a==='variant-prev'||a==='variant-next'){let i=['A','B','C'].indexOf(state.variant);setVariant(['A','B','C'][(i+(a==='variant-next'?1:2))%3])}
  else if(a==='sidebar'){state.sidebar=!state.sidebar;render()}
  else if(a==='context'){state.context=!state.context;render()}
  else if(a==='context-tab'){state.tab=arg;render()}
  else if(a==='collapse'){state.collapsed.has(arg)?state.collapsed.delete(arg):state.collapsed.add(arg);render()}
  else if(a==='collapse-chat'){state.chat=false;render()}
  else if(a==='restore-chat'){state.chat=true;render()}
  else if(a==='source'){state.selectedSource=arg;render()}
  else if(a==='filter'){state.filter=arg;render()}
  else if(a==='import')importModal(arg);
  else if(a==='close-modal')closeModal();
  else if(a==='settings'){if(arg)state.setting=arg;settings()}
  else if(a==='setting'){state.setting=arg;settings()}
  else if(a==='create-import'){let s=stories.find(x=>x.id===state.importId);let name=$('#task-name').value.trim();if(!name){notify('请填写任务名称');return}let start=$('#start-immediately').checked;let t={id:'import-'+Date.now(),title:name,source:s.id,repo:$('#task-repo').value,status:start&&count('执行中')<2?'执行中':'排队中',progress:start&&count('执行中')<2?1:0,total:5,branch:'codex/tapd-'+s.id,time:'刚刚',desc:s.desc};tasks.push(t);closeModal();openTask(t.id);notify('开发任务已创建 · 演示')}
  else if(a==='answer'){let choice=$('input[name="sync-choice"]:checked')?.value;let answeredTask=task();state.messages.push({task:answeredTask.id,text:choice==='rollback'?'方果同步失败时，回滚本地操作。':'保留本地结果，记录失败并重试。'});answeredTask.status='执行中';state.running=true;rememberTask();render();notify('已记录业务确认，任务继续执行');setTimeout(()=>{let snapshot=sessionState.get(answeredTask.id);if(answeredTask.status==='执行中'&&snapshot?.running){answeredTask.status='待审阅';answeredTask.progress=4;snapshot.running=false;if(state.selected===answeredTask.id){state.running=false;render()}else render();notify('演示任务已准备好，等待审阅')}},5000)}
  else if(a==='stop'){state.running=false;rememberTask();task().status='待回答';render();notify('已停止本轮演示生成')}
  else if(a==='file'){state.file=Number(arg);state.page='git';render()}
  else if(a==='workspace-return'){state.page='workspace';state.chat=true;render()}
  else if(a==='stage'){state.staged=!state.staged;render();notify(state.staged?'已暂存 3 个演示文件':'已取消暂存')}
  else if(a==='commit'){if(!state.staged){notify('请先暂存变更');return}if(!state.commit.trim()){notify('请填写提交信息');return}state.committed=true;render();notify('已创建演示提交，不影响真实仓库')}
  else if(a==='approve-review'){state.patchApproved=true;render();notify('已确认本次演示变更')}
  else if(a==='writeback')writeback();
  else if(a==='confirm-writeback'){if(!state.patchApproved){notify('请先返回审阅并确认变更');return}if(!$('#writeback-text').value.trim()){notify('回填内容不能为空');return}state.written=true;task().status='已完成';task().progress=5;rememberTask();closeModal();render();notify('演示回填完成，未向 TAPD 发送数据')}
  else if(a==='mode'){modal('权限模式',`<div class="option-list">${['默认权限','接受编辑','计划模式'].map(m=>btn('choose-mode:'+m,m,state.mode===m?'selected':'')).join('')}</div>`)}
  else if(a==='choose-mode'){state.mode=arg;closeModal();render()}
  else if(a==='model'){modal('选择模型',`<div class="option-list">${['Claude Sonnet','Claude Opus','Claude Haiku'].map(m=>btn('choose-model:'+m,m,state.model===m?'selected':'')).join('')}</div>`)}
  else if(a==='choose-model'){state.model=arg;closeModal();render()}
  else if(a==='effort'){state.effort=state.effort==='标准'?'深入':'标准';render()}
  else if(a==='fast'){state.fast=!state.fast;render()}
  else if(a==='source-detail'){if(task().workId){robotDemo(task());return}state.selectedSource=stories.some(s=>s.id===task().source)?task().source:stories[0].id;state.page='tapd';render()}
  else if(a==='new-task'||a==='new-session'){modal(a==='new-task'?'新建任务':'新建会话',`<label class="field">名称<input id="local-task-name" placeholder="例如：检查订单同步失败原因"></label><label class="field">项目<select id="local-task-repo"><option>lm-global-java</option><option>lanma-bankend</option><option>claude-picker</option></select></label>`,btn('close-modal','取消','secondary')+btn('create-local','创建','primary'))}
  else if(a==='create-local'){let name=$('#local-task-name').value.trim();if(!name){notify('请填写名称');return}let t={id:'local-'+Date.now(),title:name,source:null,repo:$('#local-task-repo').value,status:'排队中',progress:0,total:5,branch:'codex/local-task',time:'刚刚',desc:name};tasks.push(t);closeModal();openTask(t.id);notify('本地演示会话已创建')}
  else if(a==='search'){modal('搜索工作空间',`<label class="search-box modal-search">${icon('magnifying-glass')}<input id="global-search" placeholder="搜索任务、项目或 TAPD 编号"></label><div id="search-results">${tasks.map(t=>btn('search-task:'+t.id,`${icon('chat-circle')}<span>${t.title}<small>${t.repo} · #${t.source||'本地'}</small></span>`,'search-result')).join('')}</div>`)}
  else if(a==='search-task'){closeModal();openTask(arg)}
  else if(a==='project-menu'){modal('选择项目',`<div class="option-list">${['lm-global-java','lanma-bankend','claude-picker'].map(p=>btn('choose-project:'+p,icon('folder-simple')+p)).join('')}</div>`)}
  else if(a==='choose-project'){let t=tasks.find(t=>t.repo===arg);closeModal();if(t)openTask(t.id);else notify('该项目暂无任务，可通过新建会话添加')}
  else if(a==='task-list'){modal('任务列表',`<div class="option-list">${tasks.map(t=>btn('search-task:'+t.id,`<span>${t.title}</span>${status(t.status)}`)).join('')}</div>`)}
  else if(a==='tool-detail'){modal('工具调用详情',`<div class="tool-detail"><code>Read · service/impl/OrderLockService.java</code><p>已读取锁定与解锁实现，并整理外部同步调用点。</p><pre>batchLock(request)\n  → validateLockStatus(order)\n  → updateLockStatus(orderId, true)\n  → syncLockStatus(orderId, true)</pre><small class="muted">模拟工具结果，不读取本地文件。</small></div>`)}
  else if(a==='attach'){modal('添加上下文',`<div class="option-list">${btn('attach-tapd',icon('link')+'关联 TAPD 需求')}${btn('attach-file',icon('file-text')+'引用项目文件')}</div>`)}
  else if(a==='attach-tapd'){closeModal();state.page='tapd';render()}
  else if(a==='attach-file'){closeModal();state.draft+=' @OrderLockService.java ';render();$('#message')?.focus()}
  else if(a==='mcp-tools'){modal('TAPD 工具',`<div class="tool-catalog">${['读取我的待办','读取需求与任务','获取附件与评论','读取迭代与工作流','生成评论回填','受控状态更新'].map(n=>`<div>${icon('wrench')} ${n}${pill('演示','neutral')}</div>`).join('')}</div>`)}
  else if(a==='add-mapping'){modal('添加项目映射',`<label class="field">TAPD 项目<input id="mapping-project" placeholder="项目名称"></label><label class="field">本地仓库<input id="mapping-repo" placeholder="仓库目录名称"></label>`,btn('save-mapping','保存演示映射','primary'))}
  else if(a==='save-mapping'){if(!$('#mapping-project').value.trim()||!$('#mapping-repo').value.trim()){notify('请填写项目与仓库');return}closeModal();notify('映射已记录 · 演示，不保存到磁盘')}
  else if(a==='board-view'){notify('当前已是任务看板视图')}
  else if(a==='board-view'){notify('当前为任务看板视图')}
  else if(a==='refresh')notify('待办已刷新 · 演示数据');
  else if(a==='history'){modal('历史会话',`<div class="option-list">${['订单统计接口调整','设计记录元数据优化','模板复制流程检查'].map(t=>btn('history-open:'+t,icon('clock-counter-clockwise')+t)).join('')}</div>`)}
  else if(a==='history-open'){state.draft='继续检查：'+arg;closeModal();state.page='workspace';render();notify('历史上下文已放入输入框 · 演示')}
});
document.addEventListener('input',e=>{if(e.target.id==='message')state.draft=e.target.value;if(e.target.id==='commit-msg')state.commit=e.target.value;if(e.target.id==='font-slider'){state.font=Number(e.target.value);document.documentElement.style.setProperty('--ui-font',state.font+'px')}if(e.target.id==='tapd-search'){let p=e.target.selectionStart;state.query=e.target.value;render();$('#tapd-search').focus();$('#tapd-search').setSelectionRange(p,p)}if(e.target.id==='global-search'){let q=e.target.value.toLowerCase();$('#search-results').innerHTML=tasks.filter(t=>(t.title+t.repo+t.source).toLowerCase().includes(q)).map(t=>btn('search-task:'+t.id,`${icon('chat-circle')}<span>${t.title}<small>${t.repo} · #${t.source||'本地'}</small></span>`,'search-result')).join('')||'<p class="muted">没有找到匹配项</p>'}});
document.addEventListener('change',e=>{if(e.target.id==='auto-task'){state.auto=e.target.checked;notify(state.auto?'已开启演示规则，不会创建真实任务':'已关闭自动任务规则')}});
document.addEventListener('submit',e=>{if(e.target.id!=='message-form')return;e.preventDefault();if(!state.draft.trim())return;state.messages.push({task:task().id,text:state.draft.trim()});state.draft='';render();$('#conversation')?.scrollTo({top:$('#conversation').scrollHeight,behavior:'smooth'})});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('[data-action="search"]').click()}if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.id==='message'){$('#message-form').requestSubmit()}if(!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!e.target.isContentEditable&&!state.modal&&['ArrowLeft','ArrowRight'].includes(e.key)){let i=['A','B','C'].indexOf(state.variant);setVariant(['A','B','C'][(i+(e.key==='ArrowRight'?1:2))%3])}});
function bindDrag(){const splitter=$('.resizer');if(splitter){splitter.onpointerdown=e=>{e.preventDefault();splitter.setPointerCapture(e.pointerId);splitter.onpointermove=ev=>{let w=Math.max(290,Math.min(520,window.innerWidth-ev.clientX));$('.context-panel').style.width=w+'px'};splitter.onpointerup=()=>splitter.onpointermove=null}}const handle=$('.floating-handle');if(handle){handle.onpointerdown=e=>{if(e.target.closest('button'))return;let box=$('.floating-composer'),r=box.getBoundingClientRect(),dx=e.clientX-r.left,dy=e.clientY-r.top;handle.setPointerCapture(e.pointerId);handle.onpointermove=ev=>{box.style.left=Math.max(8,Math.min(innerWidth-box.offsetWidth-8,ev.clientX-dx))+'px';box.style.top=Math.max(55,Math.min(innerHeight-box.offsetHeight-65,ev.clientY-dy))+'px';box.style.bottom='auto';box.style.right='auto'};handle.onpointerup=()=>handle.onpointermove=null}}}
render();

if(params.get('settings')==='wecom'){state.setting='wecom';settings()}
